from pathlib import Path
p=Path('menus.js');s=p.read_text(encoding='utf-8');s+='''
function sceneArt(sheet,quadrant,className=''){const x=quadrant%2?-768:0,y=quadrant>=2?-512:0;return `<svg class="scene-art ${className}" viewBox="0 0 768 512" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="assets/world/${sheet}.png" x="${x}" y="${y}" width="1536" height="1024"/></svg>`;}
'''
for cls,sheet,q in [('art-adventure','home-scenes',0),('art-lab','home-scenes',1),('art-camp','home-scenes',2),('art-training','home-scenes',3)]:s=s.replace(f'<span class="home-art {cls}" aria-hidden="true"></span>', '${sceneArt("'+sheet+'",'+str(q)+',"home-art '+cls+'")}')
s=s.replace('<div class="training-room-banner" aria-hidden="true"><img', '<div class="training-room-banner" aria-hidden="true">${sceneArt("interiors",1,"training-banner-art")}<img')
p.write_text(s,encoding='utf-8')
p=Path('campaign-ui.js');s=p.read_text(encoding='utf-8').replace('<div class="gym-backdrop" aria-hidden="true"></div>', '<div class="gym-backdrop" aria-hidden="true">${sceneArt("gyms",({rock:0,water:1,electric:2,grass:3})[c.gym],"gym-room-art")}</div>').replace('<div class="shop-interior" aria-hidden="true"></div>', '<div class="shop-interior" aria-hidden="true">${sceneArt("interiors",0,"shop-room-art")}</div>');p.write_text(s,encoding='utf-8')
p=Path('app.js');s=p.read_text(encoding='utf-8').replace("function battleImage(mon){return mon.art||img(mon.appearance||mon.id);}","function battleImage(mon){return mon.art||`assets/pokemon/${mon.appearance||mon.id}.png`;}")
a=s.index('function transitionView(){');b=s.index('\nfunction syncBattleItems()',a);s=s[:a]+"function transitionView(){document.querySelector('.view-transition')?.remove();}\n"+s[b:];p.write_text(s,encoding='utf-8')
p=Path('dialogue.js');s=p.read_text(encoding='utf-8');a=s.index('function dialogueTick(){');b=s.index('\ndocument.addEventListener',a);s=s[:a]+'function dialogueTick(){}'+s[b:];p.write_text(s,encoding='utf-8')
