p=Path('styles.css');s=p.read_text(encoding='utf-8');s+='''
/* Preserve sprite and artwork aspect ratios; remove stretched backgrounds and post-change blur. */
html,body{width:100%;min-width:0;overflow-x:clip}#app{width:100%;min-width:0}.menu-shell,.game-shell,.battle-wrapper,.tutorial-shell{min-width:0;max-width:100%}.management-layout,.training-layout,.home-grid{min-width:0}.management-layout>* ,.training-layout>* ,.home-grid>*{min-width:0}img{object-fit:contain}img[src*="assets/pokemon/"]{object-fit:contain}.training-portrait,.scout-card-portrait img,.title-pokemon img,.evolution-orbit img,.owned-card img,.selection-slot img,.save-team img,.route-enemies img{object-fit:contain}.view-transition{display:none!important}.scene-art{display:block;position:absolute;inset:0;width:100%;height:100%;overflow:hidden;pointer-events:none}.home-art,.shop-interior,.training-room-banner,.gym-backdrop{background-image:none!important}.home-art{background:none!important}.shop-interior{background:#b6a37f}.training-room-banner{background:#cfbd96}.training-banner-art{z-index:0}.training-room-banner>img{z-index:1}.management-room:before,.training-shell:before{background-image:none!important}.route-map{background-size:cover}.npc-idle,.oak-portrait,.leader-intro-portrait{animation:npc-rest 4s ease-in-out infinite;scale:1;transform-origin:center bottom}@keyframes npc-rest{0%,100%{translate:0 0}50%{translate:0 -2px}}.tile>img,.tile>img.move-ghost{width:100%;height:145%;max-width:none;left:0;bottom:4%;object-fit:contain;object-position:center bottom}.moving-pokemon{object-fit:contain}.battle-wrapper{width:min(1120px,100%);padding:0;background:none;border:0;border-radius:0;box-shadow:none;color:#edf5de}body[data-view="battle"]{background:#263d2b;color:#edf5de}.battle-wrapper .arena{padding:18px;background-color:#66864a;background-image:repeating-linear-gradient(0deg,transparent 0 12px,#739250 12px 15px,transparent 15px 31px),repeating-linear-gradient(90deg,#6d8c4e 0 21px,#769550 21px 25px,#6d8c4e 25px 43px);background-size:auto;background-position:0 0;border:5px solid #4a6b3f;box-shadow:0 15px 50px #0d201c33,inset 0 0 0 4px #7a9856}.battle-wrapper .arena .tile:not(.reachable):not(.target-option):not(.damage-zone):not(.critical-zone):not(.selected):not(.aim){background-color:#97b570;background-image:radial-gradient(ellipse at 23% 35%,#6e984944 0 2px,transparent 3px),radial-gradient(ellipse at 70% 80%,#c5d79a55 0 2px,transparent 3px)}.battle-wrapper .arena .tile:nth-child(3n):not(.reachable):not(.target-option):not(.damage-zone):not(.critical-zone):not(.selected):not(.aim){background-color:#9cb977}.battle-wrapper .arena .tile:nth-child(7n):not(.reachable):not(.target-option):not(.damage-zone):not(.critical-zone):not(.selected):not(.aim){background-color:#92b06b}.battle-wrapper .menu-header{margin-bottom:8px}.battle-wrapper .battle-instruction{min-height:32px;font-size:17px}.battle-wrapper .top-hud{padding-bottom:10px}.battle-wrapper .bottom-hud{padding-top:12px}.battle-wrapper .arena .tile:before{opacity:.7}@media(min-width:1000px) and (min-height:600px){body[data-view="battle"] #app{padding:12px 18px}.battle-wrapper .board{height:calc(100svh - 310px);min-height:280px;max-height:530px;grid-template-rows:repeat(7,minmax(0,1fr))}.battle-wrapper .tile{aspect-ratio:auto;min-height:0}.battle-wrapper .arena{padding:14px}}@media(max-width:700px){.tile>img,.tile>img.move-ghost{width:100%;left:0;height:145%;object-fit:contain}.battle-wrapper .arena{padding:10px;border-width:3px}}@media(prefers-reduced-motion:reduce){.npc-idle,.oak-portrait,.leader-intro-portrait{animation:none}}
''';p.write_text(s,encoding='utf-8')
